// Error Analysis kit
let errFound = false;
function pickErrLine(el) {
  if (errFound || el.classList.contains('dimmed')) return;
  if (el.dataset.isError === 'true') {
    el.classList.add('flagged-correct');
    errFound = true;
    document.querySelectorAll('.err-line').forEach(o => { if (o !== el) o.classList.add('dimmed'); });
    document.getElementById('errFeedback').classList.add('visible');
  } else {
    el.classList.add('flagged-wrong');
    setTimeout(() => el.classList.remove('flagged-wrong'), 600);
  }
}
function checkErrCorrection() {
  const input = document.getElementById('errCorrection');
  const expected = document.querySelector('.err-line[data-is-error="true"]').dataset.correctLine;
  const norm = s => (s || '').toLowerCase().replace(/[−–—]/g, '-').replace(/[\s()]/g, '');
  const msg = document.getElementById('errStatusMsg');
  input.classList.remove('correct', 'incorrect');
  if (norm(input.value) === norm(expected)) {
    input.classList.add('correct');
    msg.textContent = '✓ Correct. From C(1, 1): right 6 and up 3 gives A′(7, 4). Riley\'s (9, 6) used the origin as the centre.';
  } else {
    input.classList.add('incorrect');
    msg.textContent = '✗ Not quite. Start at C(1, 1), then move right 2 × 3 and up 1 × 3.';
  }
}

// Hinge Question kit
function pickHingeOption(btn) {
  if (btn.classList.contains('dimmed')) return;
  const isCorrect = btn.dataset.correct === 'true';
  btn.classList.add('selected', isCorrect ? 'correct' : 'incorrect');
  document.querySelectorAll('.hinge-opt').forEach(o => { if (o !== btn) o.classList.add('dimmed'); });
  document.querySelectorAll('.hinge-feedback').forEach(f => f.classList.remove('visible'));
  const fbId = btn.dataset.feedbackId;
  if (fbId) document.getElementById(fbId).classList.add('visible');
}
function resetHinge() {
  document.querySelectorAll('.hinge-opt').forEach(o => o.classList.remove('selected', 'correct', 'incorrect', 'dimmed'));
  document.querySelectorAll('.hinge-feedback').forEach(f => f.classList.remove('visible'));
}

// Place the strategies: error analysis straight after the We Do,
// hinge check straight after the Quick check (before the chilli tiers).
(function () {
  const wd = document.getElementById('weDoGrid');
  const err = document.getElementById('errSection');
  if (wd && err) wd.closest('section').after(err);
  const t1 = document.getElementById('tier1');
  const hinge = document.getElementById('hingeSection');
  if (t1 && hinge) t1.before(hinge);
})();

// Topic-specific instructions for the frame's fixed section text
(function () {
  const set = (sel, html) => { const el = document.querySelector(sel); if (el) el.innerHTML = html; };
  set('#tier1-body .sec-desc', 'Type coordinates as <code>(x, y)</code>, e.g. <code>(6, -2)</code>. Type lengths and angles as just the number, and scale factors as a number or fraction, e.g. <code>2.5</code> or <code>5/2</code>.');
  set('#tier2-body .sec-desc', 'Centres that are not the origin, finding the centre, and working backwards. Count the moves from the centre, multiply them by <span class="var">k</span>, then move from the centre again.');
  set('#tier3-body .sec-desc', 'Similarity problems in context. Find the scale factor first, then use it. Type just the number (no $ or units).');
  const wd = document.getElementById('weDoGrid');
  const tip = wd && wd.parentElement.querySelector('.parts-instructions');
  if (tip) tip.innerHTML = '💡 <strong>Why we do it this way:</strong> an enlargement stretches every point away from the <em>centre</em>, so distances must be measured from the centre. Multiplying the coordinates only works when the centre is the origin. Routine: moves from the centre → multiply by <span class="var">k</span> → make the new moves from the centre.';
  const m = document.getElementById('matchArea');
  const md = m && m.parentElement.querySelector('.sec-desc');
  if (md) md.innerHTML = 'Click a card, then the card that goes with it. Image length = <span class="var">k</span> × original length. There are five matching pairs.';
})();
